def meals():
    out = []
    for n in (59, 60, 61):
        out.append('6:%d ' % n + '; '.join("'%s' ('%s', %s)" % (tr, ar, ', '.join(it)) for tr, ar, it in SEG[n]))
    return tuple(out)
